<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pdo=db();$error='';$edit=null;$id=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT);if($id){$s=$pdo->prepare('SELECT * FROM drums WHERE id=?');$s->execute([$id]);$edit=$s->fetch();if(!$edit){flash('error','Drum kit not found.');redirect('drums.php');}}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);try{if($action==='delete'){if(!$id)throw new RuntimeException('Invalid drum kit.');$s=$pdo->prepare('SELECT COUNT(*) FROM bookings WHERE drum_id=?');$s->execute([$id]);if((int)$s->fetchColumn()>0)throw new RuntimeException('This drum kit has booking history and cannot be deleted. Deactivate it instead.');$s=$pdo->prepare('DELETE FROM drums WHERE id=?');$s->execute([$id]);flash('success','Drum kit deleted.');redirect('drums.php');}elseif($action==='save'){$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$rate=filter_var($_POST['hourly_rate']??null,FILTER_VALIDATE_FLOAT);$active=isset($_POST['is_active'])?1:0;if(mb_strlen($name)<2||mb_strlen($name)>120)throw new RuntimeException('Name must be 2–120 characters.');if(mb_strlen($description)>1000)throw new RuntimeException('Description must be 1,000 characters or fewer.');if($rate===false||$rate<=0||$rate>1000000)throw new RuntimeException('Enter a valid hourly rate greater than zero.');if($id){$s=$pdo->prepare('UPDATE drums SET name=?,description=?,hourly_rate=?,is_active=? WHERE id=?');$s->execute([$name,$description,$rate,$active,$id]);flash('success','Drum kit updated.');}else{$s=$pdo->prepare('INSERT INTO drums(name,description,hourly_rate,is_active) VALUES(?,?,?,?)');$s->execute([$name,$description,$rate,$active]);flash('success','Drum kit added.');}redirect('drums.php');}else throw new RuntimeException('Unknown action.');}catch(RuntimeException $ex){$error=$ex->getMessage();}catch(Throwable $ex){error_log($ex->__toString());$error='Could not save changes. Please try again.';}}
$drums=$pdo->query('SELECT * FROM drums ORDER BY name')->fetchAll();page_header('Manage drum kits');?><div class="form-card"><h2><?=$edit?'Edit drum kit':'Add a drum kit'?></h2><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><div class="grid two"><label>Drum kit name<input name="name" maxlength="120" required value="<?=e($_POST['name']??$edit['name']??'')?>"></label><label>Hourly rate (PHP)<input type="number" name="hourly_rate" min="0.01" max="1000000" step="0.01" required value="<?=e((string)($_POST['hourly_rate']??$edit['hourly_rate']??''))?>"></label><label class="span-2">Description<textarea name="description" maxlength="1000" rows="3"><?=e($_POST['description']??$edit['description']??'')?></textarea></label><label class="check span-2"><input type="checkbox" name="is_active" value="1" <?=((int)($_POST['is_active']??$edit['is_active']??1)===1)?'checked':''?>> Available for new bookings</label></div><div class="actions"><button class="button" type="submit">Save drum kit</button><?php if($edit):?><a class="button secondary" href="drums.php">Cancel edit</a><?php endif;?></div></form></div><h2 class="section-title">All drum kits</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Hourly rate</th><th>Availability</th><th>Actions</th></tr></thead><tbody><?php foreach($drums as $d):?><tr><td><strong><?=e($d['name'])?></strong><br><small><?=e($d['description'])?></small></td><td><?=money($d['hourly_rate'])?></td><td><?=$d['is_active']?'Available':'Inactive'?></td><td class="actions compact"><a class="text-link" href="?edit=<?=(int)$d['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this drum kit? This is only possible if it has no booking history.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$d['id']?>"><button class="text-button danger-text" type="submit">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php page_footer();?>
